"use client";

type Step = {
  key: string;
  label: string;
};

type Props = {
  steps: Step[];
  activeStepKey: string;
};

export function ProcessTimeline({ steps, activeStepKey }: Props) {
  const activeIndex = steps.findIndex((s) => s.key === activeStepKey);

  return (
    <div style={{ overflowX: "auto", padding: "4px 0" }}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 0,
          minWidth: "max-content",
        }}
      >
        {steps.map((step, i) => {
          const isCompleted = i < activeIndex;
          const isActive = i === activeIndex;
          const isFuture = i > activeIndex;

          return (
            <div
              key={step.key}
              style={{ display: "flex", alignItems: "center" }}
            >
              {/* Step node */}
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  minWidth: 80,
                }}
              >
                <div
                  style={{
                    width: 36,
                    height: 36,
                    borderRadius: "50%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 13,
                    fontWeight: 600,
                    background: isCompleted
                      ? "var(--primary-green)"
                      : isActive
                        ? "var(--card-bg)"
                        : "#e9ecef",
                    color: isCompleted
                      ? "#fff"
                      : isActive
                        ? "var(--gold)"
                        : "var(--text-secondary)",
                    border: isActive
                      ? "2px solid var(--gold)"
                      : "2px solid transparent",
                    boxShadow: isActive
                      ? "0 0 0 3px rgba(194, 169, 106, 0.25)"
                      : "none",
                    transition: "all 0.2s ease",
                  }}
                >
                  {isCompleted ? (
                    <svg
                      width="16"
                      height="16"
                      viewBox="0 0 16 16"
                      fill="none"
                    >
                      <path
                        d="M3 8.5L6.5 12L13 4"
                        stroke="#fff"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                  ) : (
                    i + 1
                  )}
                </div>
                <span
                  style={{
                    marginTop: 6,
                    fontSize: 11,
                    fontWeight: isActive ? 600 : 400,
                    color: isCompleted
                      ? "var(--primary-green)"
                      : isActive
                        ? "var(--text-title)"
                        : "var(--text-secondary)",
                    textAlign: "center",
                    maxWidth: 90,
                    lineHeight: 1.3,
                    whiteSpace: "nowrap",
                  }}
                >
                  {step.label}
                </span>
              </div>

              {/* Connector line */}
              {i < steps.length - 1 && (
                <div
                  style={{
                    width: 32,
                    height: 2,
                    background:
                      i < activeIndex
                        ? "var(--primary-green)"
                        : "var(--divider)",
                    marginTop: -18,
                  }}
                />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

